const BlockStorage = require('./blockStorage');

/**
 * BackfillManager - Handles backfilling of missed events
 * Provides clean separation of backfill logic from the main listener
 */
class BackfillManager {
  constructor(contract, chainName) {
    this.contract = contract;
    this.blockStorage = new BlockStorage(chainName);
    this.chainName = chainName;
    this.lastSeenBlock = null; // Keep track of last seen block in memory
  }

  /**
   * Initialize the backfill manager by loading the last seen block
   * @returns {number|null} The last seen block number
   */
  initialize() {
    this.lastSeenBlock = this.blockStorage.loadLastSeenBlock();
    return this.lastSeenBlock;
  }

  /**
   * Handle a new block and perform backfill if needed
   * @param {number} currentBlock - The current block number
   * @param {Object} eventHandlers - Object containing event handler functions
   */
  async handleNewBlock(currentBlock, eventHandlers) {
    // Check if we need to backfill using in-memory lastSeenBlock
    if (this.lastSeenBlock && currentBlock > this.lastSeenBlock) {
      const fromBlock = this.lastSeenBlock + 1;
      const toBlock = currentBlock;

      // Only backfill if there's actually a gap (more than 1 block difference)
      if (this.blockStorage.isValidBlockRange(fromBlock, toBlock) && fromBlock < toBlock) {
        await this.performBackfill(fromBlock, toBlock, eventHandlers);
      }
      // No backfill needed for consecutive blocks - this is normal operation
    }

    // Update in-memory lastSeenBlock and save to storage
    this.lastSeenBlock = currentBlock;
    this.blockStorage.saveLastSeenBlock(currentBlock);
  }

  /**
   * Perform the actual backfill operation
   * @param {number} fromBlock - Starting block number
   * @param {number} toBlock - Ending block number
   * @param {Object} eventHandlers - Object containing event handler functions
   */
  async performBackfill(fromBlock, toBlock, eventHandlers) {
    console.log(`🔍 Backfilling events from block ${fromBlock} to ${toBlock} for ${this.chainName}`);

    try {
      // Backfill OrderCreated events
      if (eventHandlers.handleOrderCreated) {
        const createdEvents = await this.contract.queryFilter("OrderCreated", fromBlock, toBlock);
        console.log(`Found ${createdEvents.length} OrderCreated events during backfill`);
        createdEvents.forEach(event => eventHandlers.handleOrderCreated(event));
      }

      // Backfill OrderSettled events
      if (eventHandlers.handleOrderSettled) {
        const settledEvents = await this.contract.queryFilter("OrderSettled", fromBlock, toBlock);
        console.log(`Found ${settledEvents.length} OrderSettled events during backfill`);
        settledEvents.forEach(event => eventHandlers.handleOrderSettled(event));
      }

      // Backfill OrderRefunded events
      if (eventHandlers.handleOrderRefunded) {
        const refundedEvents = await this.contract.queryFilter("OrderRefunded", fromBlock, toBlock);
        console.log(`Found ${refundedEvents.length} OrderRefunded events during backfill`);
        refundedEvents.forEach(event => eventHandlers.handleOrderRefunded(event));
      }
    } catch (err) {
      console.error(`Error during backfill for ${this.chainName}:`, err.message);
    }
  }

  /**
   * Get the current last seen block from memory
   * @returns {number|null} The last seen block number
   */
  getLastSeenBlock() {
    return this.lastSeenBlock;
  }

  /**
   * Manually clear the storage (useful for testing/reset)
   */
  clearStorage() {
    this.blockStorage.clearStorage();
  }
}

module.exports = BackfillManager;

const fs = require('fs');
const path = require('path');

/**
 * BlockStorage - Handles persistent storage of last seen block numbers
 * Provides chain-specific file storage with automatic cleanup
 */
class BlockStorage {
  constructor(chainName = 'unknown') {
    this.chainName = chainName;
    // Uses RPC URL for unique file naming
    const rpcUrl = process.env.RPC_WS_URL || 'unknown';
    const fileSuffix = this._extractFileSuffix(rpcUrl);
    this.storageFile = path.join(__dirname, `lastBlock_${fileSuffix}.txt`);
    this.maxFileAge = 3600000; // 1 hour in milliseconds
  }

  /**
   * Extract a safe file suffix from RPC URL
   * @param {string} rpcUrl - The RPC URL
   * @returns {string} Safe file suffix
   */
  _extractFileSuffix(rpcUrl) {
    try {
      // Handle null/undefined/empty values(Shouldn't happen but just in case)
      if (!rpcUrl || typeof rpcUrl !== 'string') {
        return 'unknown';
      }

      // Handle different URL formats
      let domain = 'unknown';

      if (rpcUrl.includes('://')) {
        // Full URL: wss://mainnet.base.org or https://rpc.lisk.com
        const urlParts = rpcUrl.split('/');
        domain = urlParts[2] || 'unknown';
      } else if (rpcUrl.includes('.')) {
        // Domain only: mainnet.base.org
        domain = rpcUrl;
      } else {
        // Fallback: use the whole string
        domain = rpcUrl;
      }

      // Clean domain: remove all non-alphanumeric characters
      const cleanDomain = domain.replace(/[^a-zA-Z0-9]/g, '');

      // Ensure we have at least 3 characters, take last 8 max
      if (cleanDomain.length === 0) {
        return 'unknown';
      } else if (cleanDomain.length <= 8) {
        return cleanDomain;
      } else {
        return cleanDomain.slice(-8);
      }
    } catch (error) {
      console.warn(`⚠️ Error parsing RPC URL "${rpcUrl}":`, error.message);
      return 'unknown';
    }
  }

  /**
   * Load the last seen block number from persistent storage
   * Automatically clears old files to prevent stale data
   * @returns {number|null} The last seen block number or null if not found/invalid
   */
  loadLastSeenBlock() {
    try {
      if (fs.existsSync(this.storageFile)) {
        const stats = fs.statSync(this.storageFile);
        const fileAge = Date.now() - stats.mtime.getTime();

        // If file is older than maxFileAge, automatically clear it
        if (fileAge > this.maxFileAge) {
          console.log(`🔄 Last block file for ${this.chainName} is too old (${Math.round(fileAge / 1000 / 60)} minutes), automatically clearing`);
          this.clearStorage();
          return null;
        }

        const content = fs.readFileSync(this.storageFile, 'utf8').trim();
        const blockNumber = parseInt(content);
        if (!isNaN(blockNumber)) {
          console.log(`📁 Loaded last seen block for ${this.chainName}: ${blockNumber}`);
          return blockNumber;
        } else {
          // Invalid content in file, clear it
          console.log(`🔄 Invalid content in block file for ${this.chainName}, automatically clearing`);
          this.clearStorage();
        }
      }
    } catch (err) {
      console.warn(`⚠️ Could not load last block file for ${this.chainName}:`, err.message);
      // If there's an error reading the file, try to clear it
      this.clearStorage();
    }
    return null;
  }

  /**
   * Save the current block number to persistent storage
   * @param {number} blockNumber - The block number to save
   */
  saveLastSeenBlock(blockNumber) {
    try {
      fs.writeFileSync(this.storageFile, blockNumber.toString());
      console.log(`Saved last seen block for ${this.chainName}: ${blockNumber}`);
    } catch (err) {
      console.error(`Could not save last block for ${this.chainName}:`, err.message);
    }
  }

  /**
   * Check if a block range is valid for backfilling
   * @param {number} fromBlock - Starting block number
   * @param {number} toBlock - Ending block number
   * @returns {boolean} True if the range is valid
   */
  isValidBlockRange(fromBlock, toBlock) {
    return fromBlock <= toBlock && fromBlock > 0 && toBlock > 0;
  }

  /**
   * Get the storage file path (useful for debugging)
   * @returns {string} The full path to the storage file
   */
  getStoragePath() {
    return this.storageFile;
  }

  /**
   * Manually clear the storage file (useful for testing/reset)
   */
  clearStorage() {
    try {
      if (fs.existsSync(this.storageFile)) {
        fs.unlinkSync(this.storageFile);
        console.log(`Cleared storage file for ${this.chainName}`);
      }
    } catch (err) {
      console.error(`Could not clear storage file for ${this.chainName}:`, err.message);
    }
  }

  /**
   * Clean up old storage files for all chains (startup maintenance)
   * This is a class method that can be called to clean up stale files
   */
  static cleanupOldFiles() {
    try {
      const files = fs.readdirSync(__dirname);
      const blockFiles = files.filter(file => file.startsWith('lastBlock_') && file.endsWith('.txt'));

      let cleanedCount = 0;
      blockFiles.forEach(file => {
        const filePath = path.join(__dirname, file);
        const stats = fs.statSync(filePath);
        const fileAge = Date.now() - stats.mtime.getTime();

        if (fileAge > 3600000) { // 1 hour
          fs.unlinkSync(filePath);
          const fileSuffix = file.replace('lastBlock_', '').replace('.txt', '');
          console.log(`🧹 Cleaned up old storage file ${fileSuffix} (${Math.round(fileAge / 1000 / 60)} minutes old)`);
          cleanedCount++;
        }
      });

      if (cleanedCount > 0) {
        console.log(`🧹 Cleanup complete: removed ${cleanedCount} old storage files`);
      }
    } catch (err) {
      console.warn('⚠️ Could not perform storage cleanup:', err.message);
    }
  }
}

module.exports = BlockStorage;

require('dotenv').config();
const { ethers } = require('ethers');
const { createHmac } = require('node:crypto');
const axios = require('axios');
const abi = require('./abi.json');
const BackfillManager = require('./backfillManager');
const BlockStorage = require('./blockStorage');

let provider, contract;
let reconnectAttempts = 0;
const MAX_RECONNECTS = 5;

let lastBlockTime = Date.now();
let backfillManager = null;

// Chain configuration
const LISTENER_CHAIN = process.env.LISTENER_CHAIN || 'unknown';

const FASTAPI_BASE_URL = process.env.FASTAPI_BASE_URL;
const LISTENER_SECRET  = process.env.LISTENER_WEBHOOK_SECRET;



function signBody(timestamp, rawBody) {
  const mac = createHmac('sha256', Buffer.from(LISTENER_SECRET, 'utf8'))
    .update(`${timestamp}.${rawBody}`, 'utf8')
    .digest('hex');
  return `v1=${mac}`;
}

async function postSigned(path, payload) {
  const ts  = Math.floor(Date.now() / 1000).toString();
  const raw = JSON.stringify(payload);
  const sig = signBody(ts, raw);

  return axios.post(`${FASTAPI_BASE_URL}${path}`, raw, {
    headers: {
      'Content-Type': 'application/json',
      'X-EP-Timestamp': ts,
      'X-EP-Signature': sig,
      'X-EP-Client': 'listener',
    },
  });
}

const processedOrderCreated = new Set();
const processedOrderSettled = new Set();
const processedOrderRefunded = new Set();

// --- Setup Event Handlers ---
async function handleOrderCreated(...args) {
  const event = args[args.length - 1];
  const orderId = event.args?.orderId?.toString() || "";

  // Idempotency check
  if (processedOrderCreated.has(orderId)) {
    console.log(`⏩ Skipping duplicate OrderCreated for orderId: ${orderId}`);
    return;
  }
  processedOrderCreated.add(orderId);

  console.log("📥 OrderCreated received:", event.args);

  const payload = {
    orderId: orderId,
    requester: event.args?.requester || "",
    token: event.args?.token || "",
    amount: event.args?.amount?.toString() || "0",
    messageHash: event.args?.messageHash || "",
    orderType: Number(event.args?.orderType ?? 0),
    transactionHash: event.log?.transactionHash?.toString() || ""
  };

  try {
    const res = await postSigned("/events/order-created", payload);

    console.log("✅ OrderCreated forwarded:", res.data);
  } catch (err) {
  if (err.response) {
    console.error("❌ OrderCreated forwarding failed with status:", err.response.status);
    console.error("📨 Response data:", err.response.data);
  } else {
    console.error("❌ OrderCreated forwarding failed:", err.message);
  }
  console.error("📦 Payload:", payload);
}

}

async function handleOrderSettled(...args) {
  const event = args[args.length - 1];
  const orderId = event.args?.orderId?.toString() || event.args[0]?.toString() || "";
  // Idempotency check
  if (processedOrderSettled.has(orderId)) {
    console.log(`⏩ Skipping duplicate OrderSettled for orderId: ${orderId}`);
    return;
  }
  processedOrderSettled.add(orderId);

  console.log("📥 OrderSettled received:", event.args);

  const payload = {
    orderId: orderId,
    transactionHash: event?.log?.transactionHash || null
  };

  try {
    const res = await postSigned("/events/order-settled", payload);
    console.log("✅ OrderSettled forwarded:", res.data);
  } catch (err) {
    console.error("❌ OrderSettled forwarding failed:", err.message);
    console.error("📦 Payload:", payload);
  }
}

async function handleOrderRefunded(...args) {
  const event = args[args.length - 1];
  const orderId = event.args?.orderId?.toString() || event.args[0]?.toString() || "";

  // Idempotency check
  if (processedOrderRefunded.has(orderId)) {
    console.log(`⏩ Skipping duplicate OrderRefunded for orderId: ${orderId}`);
    return;
  }
  processedOrderRefunded.add(orderId);

  console.log("📥 OrderRefunded received:", event.args);

  const payload = {
    orderId: orderId,
    transactionHash: event?.log?.transactionHash || null
  };

  try {
    const res = await postSigned("/events/order-refunded", payload);
    console.log("✅ OrderRefunded forwarded:", res.data);
  } catch (err) {
    console.error("❌ OrderRefunded forwarding failed:", err.message);
    console.error("📦 Payload:", payload);
  }
}

// --- Reconnection Logic ---
function reconnectWithBackoff() {
  if (reconnectAttempts >= MAX_RECONNECTS) {
    console.error("🛑 Max reconnection attempts reached. Exiting.");
    reconnectAttempts = 0;
  }

  const delay = Math.min(5000 * 2 ** reconnectAttempts, 30000);
  console.warn(`🔁 Reconnecting in ${delay / 1000}s... (Attempt ${reconnectAttempts + 1})`);
  setTimeout(() => {
    reconnectAttempts++;
    setupListeners();
  }, delay);
}

// --- Setup Listeners ---
function setupListeners() {
  console.log("🔧 Initializing provider and listeners...");

  // Clean up old storage files on startup (senior dev practice)
  BlockStorage.cleanupOldFiles();

  provider = new ethers.WebSocketProvider(process.env.RPC_WS_URL);
  contract = new ethers.Contract(process.env.CONTRACT_ADDRESS, abi, provider);

  // Initialize backfill manager
  backfillManager = new BackfillManager(contract, LISTENER_CHAIN);
  backfillManager.initialize();

  contract.removeAllListeners(); 
  console.log("🧹 Removed existing listeners.");

  // Keep-alive
  provider.on("block", async (blockNumber) => {
    console.log("💓 New block:", blockNumber);
    lastBlockTime = Date.now();

    // Handle backfill through the BackfillManager
    if (backfillManager) {
      await backfillManager.handleNewBlock(blockNumber, {
        handleOrderCreated,
        handleOrderSettled,
        handleOrderRefunded
      });
    }
  });

  // Reconnect if no blocks are received for 60s
  setInterval(() => {
    if (Date.now() - lastBlockTime > 60000) {
      console.warn("⚠️ No blocks for 60s. Forcing reconnect...");
      provider.destroy?.(); // ethers v6
      setupListeners(); // Reinitialize
    }
  }, 30000);

  provider._websocket?.on("open", () => {
    reconnectAttempts = 0;
    console.log("✅ WebSocket connected");
  });

  provider._websocket?.on("close", (code, reason) => {
    console.warn(`⚠️ WebSocket closed: ${code} - ${reason}`);
    reconnectWithBackoff();
  });

  provider._websocket?.on("error", (err) => {
    console.error("❌ WebSocket error:", err.message);
  });

  // Register event listeners
  contract.on("OrderCreated", handleOrderCreated);
  contract.on("OrderSettled", handleOrderSettled);
  contract.on("OrderRefunded", handleOrderRefunded);

  console.log("🟢 Listeners registered. Awaiting events...");
}

// ──────────────────────────────────────────────────────────────
// Health endpoint
// ──────────────────────────────────────────────────────────────
const express = require('express');
const healthApp = express();
const healthPort = process.env.HEALTH_PORT || 3000;

healthApp.get('/healthz', (_req, res) => {
  const isStale = Date.now() - lastBlockTime > 60000;
  res.json({
    status: isStale ? 'stale' : 'ok',
    lastBlock: lastBlockTime,
    uptime: process.uptime(),
  });
});


healthApp.listen(healthPort, () => {
  console.log(`🩺 Health check listening on port ${healthPort}`);
});

setupListeners();

